%% ========================================================================
%% METASURFACE 1-BIT BEAM STEERING & AUTOMATIC DATA EXPORTER (AUTO-BOUND ENGINE)
%% ========================================================================
clear; clc; close all;

%% [PREREQUISITE INFO] DATABASE CONFIGURATION
% Profile array of pre-simulated incident angles available in the local database
available_angles = [0, 15, 30, 45, 60]; 

fprintf('=================================================================\n'); %[output:3ba68c34]
fprintf('         RIS PHASE INTERPOLATION & BEAM STEERING SYSTEM\n'); %[output:8d9b37c8]
fprintf('=================================================================\n'); %[output:814901cd]
fprintf('--> Please ensure the following lookup files exist in the current directory:\n'); %[output:16c28476]
for a = available_angles %[output:group:9b6fe06b]
    fprintf('    - matrix_%d_ON.txt  and  matrix_%d_OFF.txt\n', a, a); %[output:33382b20]
end %[output:group:9b6fe06b]
fprintf('=================================================================\n\n'); %[output:6c7581af]


%% 1. SYSTEM CONFIGURATION & ARRAY GEOMETRICS
f_target  = 26e9;               % Target operating frequency (26 GHz)
c         = 2.99792458e8;       % Speed of light in free space (m/s)
lambda    = c / f_target;       % Free-space wavelength (m)
k0        = 2 * pi / lambda;    % Free-space wavenumber

% Physical specifications of the RIS aperture
Nx        = 32;                 % Number of unit cells along the X-axis
Ny        = 32;                 % Number of unit cells along the Y-axis
d         = 5.5e-3;             % Center-to-center element spacing / pitch (5.5 mm)
W_plate   = Nx * d;             % Total physical aperture width of the RIS panel

% Generate 2D physical coordinate matrices for the spatial array grid
[X_pos, Y_pos] = meshgrid(((1:Nx) - (Nx+1)/2) * d, ((1:Ny) - (Ny+1)/2) * d);


%% 2. USER SETTINGS: OPERATIONAL ANGLES
theta_i_deg = 55;               % Operational incident angle (Degrees) -> Engine will auto-interpolate if missing
theta_s_deg = 60;               % Target desired scattering/reflection angle (Degrees)

% Convert targeted simulation angles from degrees to radians
theta_i = deg2rad(theta_i_deg);
theta_s = deg2rad(theta_s_deg);


%% 3. AUTOMATED SMART SEARCH & SEARCH-BOUND ENGINE
% Automatically locate the nearest Lower Bound and Upper Bound constraints

if any(available_angles == theta_i_deg)
    % Case 1: Exact match found in database -> Interpolation bypassed
    theta_low  = theta_i_deg;
    theta_high = theta_i_deg;
    is_exact   = true;
else
    % Case 2: Mismatch found -> Determine neighboring bounds dynamically
    is_exact   = false;
    
    % Exception Handling: Clamp behavior for out-of-bound incident profiles
    if theta_i_deg < available_angles(1)
        theta_low  = available_angles(1);
        theta_high = available_angles(1);
    elseif theta_i_deg > available_angles(end)
        theta_low  = available_angles(end);
        theta_high = available_angles(end);
    else
        % Dynamic Search Matrix: Enclosing interval isolation
        theta_low  = available_angles(find(available_angles < theta_i_deg, 1, 'last'));
        theta_high = available_angles(find(available_angles > theta_i_deg, 1, 'first'));
    end
end


%% 4. UNIT CELL PHASE DATA LOADER & COMPLEX VECTOR INTERPOLATION
try %[output:group:6f4b1589]
    if is_exact
        % Direct Profile Loading: Extract exact match configuration
        filename_ON  = sprintf('matrix_%d_ON.txt', theta_i_deg);
        filename_OFF = sprintf('matrix_%d_OFF.txt', theta_i_deg);
        
        data_ON  = load(filename_ON); data_OFF = load(filename_OFF);
        [~, idx] = min(abs(data_ON(:,1) - (f_target / 1e9)));
        
        phase_ON_real  = data_ON(idx, 2);   
        phase_OFF_real = data_OFF(idx, 2); 
        fprintf('--> [Exact Match] Profile verified for %d°: Phase ON = %.2f°, OFF = %.2f°\n', ...
                theta_i_deg, phase_ON_real, phase_OFF_real);
    else
        % Boundary Profile Loading: Extract adjacent matrices for mathematical prediction
        fprintf('--> [Auto-Detect] Target angle %d° bounded between %d° and %d°\n', theta_i_deg, theta_low, theta_high); %[output:094a8be2]
        fprintf('    Loading lookup bounds: [%d°] and [%d°] for phase estimation...\n', theta_low, theta_high); %[output:7197fe3f]
        
        filename_ON_low   = sprintf('matrix_%d_ON.txt', theta_low);
        filename_OFF_low  = sprintf('matrix_%d_OFF.txt', theta_low);
        filename_ON_high  = sprintf('matrix_%d_ON.txt', theta_high);
        filename_OFF_high = sprintf('matrix_%d_OFF.txt', theta_high);
        
        data_ON_low   = load(filename_ON_low);  data_OFF_low  = load(filename_OFF_low);
        data_ON_high  = load(filename_ON_high); data_OFF_high = load(filename_OFF_high);
        
        [~, idx] = min(abs(data_ON_low(:,1) - (f_target / 1e9)));
        
        p_ON_low   = data_ON_low(idx, 2);  p_OFF_low  = data_OFF_low(idx, 2);
        p_ON_high  = data_ON_high(idx, 2); p_OFF_high = data_OFF_high(idx, 2);
        
        % Calculate linear scaling coefficient weight
        weight = (theta_i_deg - theta_low) / (theta_high - theta_low);
        
        % Mathematical Transformation: Interpolate via complex exponential fields to prevent phase-wrapping errors
        vec_ON_interp  = (1 - weight)*exp(1i*deg2rad(p_ON_low)) + weight*exp(1i*deg2rad(p_ON_high));
        phase_ON_real  = rad2deg(angle(vec_ON_interp));
        
        vec_OFF_interp = (1 - weight)*exp(1i*deg2rad(p_OFF_low)) + weight*exp(1i*deg2rad(p_OFF_high));
        phase_OFF_real = rad2deg(angle(vec_OFF_interp));
        
        fprintf('--> [Prediction Success] Phase estimation completed:\n'); %[output:715844b8]
        fprintf('    Estimated Phase ON: %.2f°, Phase OFF: %.2f°\n', phase_ON_real, phase_OFF_real); %[output:0455e805]
    end
catch
    % Resilient Fallback State: Trigger ideal 180-degree states upon IO exception
    warning('Unable to read profile data matrices! Reverting to fallback ideal states (ON=0°, OFF=180°).');
    phase_ON_real  = 0;   
    phase_OFF_real = 180; 
end %[output:group:6f4b1589]

% Convert unified phase profiles to radians for spatial matrix deployment
psi_ON  = deg2rad(phase_ON_real);
psi_OFF = deg2rad(phase_OFF_real);


%% 5. WAVEFRONT ANALYSIS (INCIDENT + SCATTERING PHASE COMPENSATION)
phase_incident = -k0 * X_pos * sin(theta_i); 
phase_scatter  =  k0 * X_pos * sin(theta_s); 
phase_required = wrapToPi(phase_scatter - phase_incident);


%% 6. 1-BIT DIGITAL QUANTIZATION LOGIC (COMPLEX VECTOR OPTIMIZATION)
coding_matrix = zeros(Ny, Nx);
R_actual_mesh = zeros(Ny, Nx); 

for m = 1:Ny
    for n = 1:Nx
        phi_req = phase_required(m, n);
        
        % Quantization Mapping: Minimize vector metric distance on the complex unit circle arc
        dist_to_ON  = abs(exp(1i*phi_req) - exp(1i*psi_ON));
        dist_to_OFF = abs(exp(1i*phi_req) - exp(1i*psi_OFF));
        
        if dist_to_ON < dist_to_OFF
            coding_matrix(m, n) = 1; 
            R_actual_mesh(m, n) = exp(1i * psi_ON);  
        else
            coding_matrix(m, n) = 0; 
            R_actual_mesh(m, n) = exp(1i * psi_OFF); 
        end
    end
end


%% 7. FAR-FIELD RADIATION PATTERN EMULATION (FINITE PLATE SPECULAR COUPLING)
theta_scan = -90:0.5:90; 
pattern_total = zeros(size(theta_scan));
weight_specular = 3.5;              % Empirical tuning coefficient for finite-size structural ground scattering

for t = 1:length(theta_scan)
    th_rad = deg2rad(theta_scan(t));
    
    % Summation of discrete array factor components generated by active pixel states
    E_metasurface = sum(sum(R_actual_mesh .* exp(-1i * k0 * X_pos * (sin(theta_i) + sin(th_rad)))));
    
    % Analytical sinc function modeling finite physical plate aperture scattering
    psi_plate = (k0 * W_plate * (sin(th_rad) + sin(theta_i))) / 2;
    if psi_plate == 0
        E_specular = 1;
    else
        E_specular = sin(psi_plate) / psi_plate;
    end
    E_specular = E_specular * (Nx * Ny) * weight_specular; 
    
    % Superposition of complex scattering components (Metasurface Field + Specular Leakage)
    pattern_total(t) = abs(E_metasurface + E_specular);
end

% Normalize field vector power spectrum to 0 dB peak reference
pattern_dB = 20 * log10(pattern_total);
pattern_dB = pattern_dB - max(pattern_dB);


%% 8. DATA VISUALIZATION
fig = figure('Color', [1 1 1], 'Position', [100, 100, 1000, 450]); %[output:2e6d57a2]

% Left Subplot: 2D Spatial Layout of Binary Coding State Array
subplot(1,2,1); %[output:2e6d57a2]
imagesc(coding_matrix); %[output:2e6d57a2]
colormap([0 0 0; 1 0.84 0]);  %[output:2e6d57a2]
colorbar('Ticks', [0, 1], 'TickLabels', {'OFF (0)', 'ON (1)'}); grid on; %[output:2e6d57a2]
set(gca, 'XTick', 1:4:Nx, 'YTick', 1:4:Ny); %[output:2e6d57a2]
xlabel('Cell Index (X-axis)'); ylabel('Cell Index (Y-axis)'); %[output:2e6d57a2]
title(sprintf('1-Bit Coding Layout (In: %d° \\rightarrow Out: %d°)', theta_i_deg, theta_s_deg)); %[output:2e6d57a2]

% Right Subplot: Predicted Normalized Far-Field Radiation Profile
subplot(1,2,2); %[output:2e6d57a2]
plot(theta_scan, pattern_dB, 'LineWidth', 2.5, 'Color', [0 0.4470 0.7410]); %[output:2e6d57a2]
hold on; %[output:2e6d57a2]
xline(theta_s_deg, '--r', 'Desired Reflection', 'LineWidth', 1.5, 'LabelVerticalAlignment', 'bottom'); %[output:2e6d57a2]
xline(-theta_i_deg, '--b', 'Specular Leakage', 'LineWidth', 1.5, 'LabelVerticalAlignment', 'bottom'); %[output:2e6d57a2]
grid on; xlim([-90 90]); ylim([-35 0]); %[output:2e6d57a2]
xlabel('Observation Angle, \theta (deg)'); ylabel('Relative Power Pattern (dB)'); %[output:2e6d57a2]
title('Predicted Far-Field Radiation Pattern (CST Emulation)'); %[output:2e6d57a2]


%% 9. AUTOMATIC DATA EXPORT SYSTEM
fprintf('\n--> Exporting simulation artifacts to local directory...\n'); %[output:7b9adb6c]
folder_name = sprintf('RIS_Output_In%d_Out%d', theta_i_deg, theta_s_deg);
if ~exist(folder_name, 'dir'), mkdir(folder_name); end

% Export high-resolution PNG plot artifact
image_path = fullfile(folder_name, 'RIS_Radiation_Pattern_Plot.png');
saveas(fig, image_path); %[output:2e6d57a2]

% Export numerical trace coordinates [Angle vs Normalized RCS Power]
data_matrix = [theta_scan', pattern_dB'];
data_path = fullfile(folder_name, 'Graph_Values_RCS_Data.txt');
fid = fopen(data_path, 'w');
fprintf(fid, '%%%% RCS Prediction Data (Incident: %d deg, Target: %d deg)\n', theta_i_deg, theta_s_deg);
fprintf(fid, '%%%% Column 1: Angle (deg) | Column 2: Power (dB)\n');
fclose(fid);
dlmwrite(data_path, data_matrix, '-append', 'delimiter', '\t', 'precision', '%.4f');

% Export raw binary 32x32 layout file ready for CST Macro or FPGA compilation
matrix_path = fullfile(folder_name, 'Coding_Matrix_32x32.txt');
dlmwrite(matrix_path, coding_matrix, 'delimiter', ' ');

fprintf('Execution completed successfully! Exported files to "%s"\n', folder_name); %[output:657f1f98]

